#include QMK_KEYBOARD_H

enum layers {
    _BASE = 0,
    _FN1,
    _FN2
};

// Defines the keycodes used by our macros in process_record_user
enum custom_keycodes {
    QMKBEST = SAFE_RANGE,
    QMKURL
};

const uint16_t PROGMEM keymaps[][MATRIX_ROWS][MATRIX_COLS] = {
    [_BASE] = LAYOUT_ortho_4x4(
        KC_PGUP,  KC_HOME, KC_UP,   KC_END,
        KC_PGDN,  KC_LEFT, KC_DOWN, KC_RGHT,
        MO(_FN2), KC_VOLU, KC_MPLY, KC_MPRV,
        MO(_FN1), KC_VOLD, KC_MUTE, KC_MNXT
    ),
    [_FN1] = LAYOUT_ortho_4x4(
        KC_ESC,  KC_P7,   KC_P8,   KC_P9,
        KC_TAB,  KC_P4,   KC_P5,   KC_P6,
        KC_ENT,  KC_P1,   KC_P2,   KC_P3,
        _______, KC_P0,   KC_P0,   KC_DOT
    ),
    [_FN2] = LAYOUT_ortho_4x4(
        UG_TOGG, UG_HUEU, UG_SATU, UG_VALU,
        UG_NEXT, UG_HUED, UG_SATD, UG_VALD,
        _______, _______, _______, QK_BOOT,
        BL_STEP, _______, QMKBEST, QMKURL
    )
};

bool process_record_user(uint16_t keycode, keyrecord_t *record) {
    switch (keycode) {
        case QMKBEST:
            if (record->event.pressed) {
                // when keycode QMKBEST is pressed
                SEND_STRING("QMK is the best thing ever!");
            }
            break;
        case QMKURL:
            if (record->event.pressed) {
                // when keycode QMKURL is pressed
                SEND_STRING("https://qmk.fm/\n");
            }
            break;
    }
    return true;
}
